/**
 * The week's lineup, chosen in code before any AI call (#95).
 *
 * `buildWeekSlate` decides each day's cuisine, protein, cooking method and
 * pantry focus, so variety is enforced rather than only requested. Each
 * day is then generated by its own request, all in parallel, with its slot
 * as hard constraints. Pure and deterministic for a given `seed`.
 */

import type { FamilySettings } from './types/settings';

export type DayType = 'weeknight' | 'weekend';

export interface DaySlot {
  /** 0 = Monday … 6 = Sunday. */
  index: number;
  type: DayType;
  /** A CUISINE_OPTIONS id, or null when the household picked none. */
  cuisine: string | null;
  protein: string;
  method: string;
  /** Pantry items this day should use, at most MAX_PANTRY_FOCUS. */
  pantryFocus: string[];
}

export interface WeekSlateInput {
  settings: Pick<FamilySettings, 'dietaryType' | 'dairyFree' | 'allergies' | 'avoidFoods' | 'effortPreference'>;
  /** This week's cuisines (the wizard's pick, else the household's). */
  cuisines: string[];
  pantryItems?: string[];
  /** Pantry items to use first; they land on Monday–Wednesday. */
  useSoonItems?: string[];
  /** Cuisines of last week's meals; preferred less this week. */
  recentCuisines?: string[];
  seed: number;
}

export const WEEK_DAYS = 7;
export const MAX_PANTRY_FOCUS = 3;
/** No protein more than this many times a week (relaxed only when the diet allows too few). */
export const MAX_PROTEIN_PER_WEEK = 2;
/** Omnivore weeks include exactly one meat-free night. */
export const VEGETARIAN_NIGHT = 'vegetarian (no meat or fish)';

export const WEEKNIGHT_METHODS = ['stir-fry', 'roast/bake', 'one-pot/braise', 'grill/pan-fry', 'pasta/noodles', 'salad/bowl'];
/** With minimal clean-up, weeknights favour these. */
export const LOW_CLEANUP_METHODS = ['one-pot/braise', 'roast/bake', 'salad/bowl'];
export const WEEKEND_METHODS = [...WEEKNIGHT_METHODS, 'slow-cook'];

const PROTEINS_BY_DIET: Record<FamilySettings['dietaryType'], string[]> = {
  omnivore: ['chicken', 'beef', 'pork', 'lamb', 'fish', 'seafood', VEGETARIAN_NIGHT],
  flexitarian: ['legumes', 'tofu', 'eggs', 'halloumi', 'chicken', 'fish'],
  pescatarian: ['fish', 'seafood', 'eggs', 'legumes', 'tofu'],
  vegetarian: ['eggs', 'legumes', 'tofu', 'paneer', 'halloumi'],
  vegan: ['tofu', 'tempeh', 'legumes', 'seitan'],
};

/** When allergies rule out every protein the diet allows. */
const ANY_PROTEIN = 'any protein that suits the diet and allergies';

/** Flexitarian: meat or fish at most this many nights. */
const FLEXITARIAN_MEAT_NIGHTS = 2;
const MEAT_OR_FISH = new Set(['chicken', 'beef', 'pork', 'lamb', 'fish', 'seafood']);
const DAIRY_PROTEINS = new Set(['paneer', 'halloumi']);

/**
 * Words in an allergy or avoid-food entry that rule a protein out, beyond
 * its own name (e.g. "shellfish" rules out seafood, "soy" rules out tofu).
 * Matched as whole words (plurals allowed), so "peanuts" doesn't rule out
 * legumes and "shellfish" doesn't rule out fish.
 */
const EXCLUDED_BY: Record<string, string[]> = {
  chicken: ['chicken', 'poultry'],
  beef: ['beef', 'red meat'],
  pork: ['pork', 'bacon', 'ham'],
  lamb: ['lamb', 'red meat'],
  fish: ['fish', 'seafood'],
  seafood: ['seafood', 'shellfish', 'prawn', 'shrimp', 'crustacean', 'mollusc', 'squid'],
  eggs: ['egg'],
  legumes: ['legume', 'lentil', 'chickpea', 'bean'],
  tofu: ['tofu', 'soy'],
  tempeh: ['tempeh', 'soy'],
  seitan: ['seitan', 'gluten', 'wheat'],
  paneer: ['paneer', 'dairy', 'milk', 'cheese', 'lactose'],
  halloumi: ['halloumi', 'dairy', 'milk', 'cheese', 'lactose'],
};

/** The proteins this household can have, before any rotation. */
export function allowedProteins(settings: WeekSlateInput['settings']): string[] {
  const avoid = [...settings.allergies, ...settings.avoidFoods].map((item) => item.toLowerCase().trim()).filter(Boolean);
  return PROTEINS_BY_DIET[settings.dietaryType].filter((protein) => {
    if (settings.dairyFree && DAIRY_PROTEINS.has(protein)) return false;
    const words = EXCLUDED_BY[protein] ?? [];
    return !avoid.some((item) => words.some((word) => new RegExp(`\\b${word}(?:s|es)?\\b`).test(item)));
  });
}

export function buildWeekSlate(input: WeekSlateInput): DaySlot[] {
  const random = mulberry32(input.seed);
  const types = Array.from({ length: WEEK_DAYS }, (_, index): DayType => (index >= 5 ? 'weekend' : 'weeknight'));
  const cuisines = pickCuisines(input.cuisines, input.recentCuisines ?? [], random);
  const proteins = bringUseSoonProteinsForward(pickProteins(input.settings, random), input.useSoonItems ?? []);
  const methods = pickMethods(types, input.settings.effortPreference, random);
  const pantry = pickPantryFocus(input.pantryItems ?? [], input.useSoonItems ?? [], proteins);

  return types.map((type, index) => ({
    index,
    type,
    cuisine: cuisines[index],
    protein: proteins[index],
    method: methods[index],
    pantryFocus: pantry[index],
  }));
}

/**
 * One day's slot for a swap or single-day generation (#95): the same rules,
 * built against the rest of the current week so it differs from its
 * neighbours and from proteins already used twice.
 */
export function buildDaySlot(
  input: WeekSlateInput & {
    index: number;
    /** Proteins on the week's other days, if known. */
    weekProteins?: (string | null | undefined)[];
    /** Cuisines on the week's other days, if known. */
    weekCuisines?: (string | null | undefined)[];
  }
): DaySlot {
  const random = mulberry32(input.seed);
  const index = input.index;
  const type: DayType = index >= 5 ? 'weekend' : 'weeknight';
  const neighbours = [index - 1, index + 1];
  const neighbourValues = (values: (string | null | undefined)[] | undefined) =>
    new Set(neighbours.map((i) => values?.[i]).filter((value): value is string => Boolean(value)));

  const cuisinePool = shuffle(input.cuisines, random);
  const nearbyCuisines = neighbourValues(input.weekCuisines);
  const cuisine = cuisinePool.find((c) => !nearbyCuisines.has(c)) ?? cuisinePool[0] ?? null;

  const counts = countOf(input.weekProteins?.filter((_, i) => i !== index) ?? []);
  const nearbyProteins = neighbourValues(input.weekProteins);
  const proteinPool = shuffle(allowedProteins(input.settings), random);
  const protein =
    proteinPool.find((p) => !nearbyProteins.has(p) && (counts.get(p) ?? 0) < MAX_PROTEIN_PER_WEEK) ??
    proteinPool.find((p) => !nearbyProteins.has(p)) ??
    proteinPool[0] ??
    ANY_PROTEIN;

  const methods = shuffle(methodsFor(type, input.settings.effortPreference), random);
  const dayProteins = Array.from({ length: WEEK_DAYS }, (_, i) => (i === index ? protein : input.weekProteins?.[i] ?? ''));
  const pantry = pickPantryFocus(input.pantryItems ?? [], input.useSoonItems ?? [], dayProteins);

  return { index, type, cuisine, protein, method: methods[0], pantryFocus: pantry[index] };
}

function pickCuisines(cuisines: string[], recent: string[], random: () => number): (string | null)[] {
  const unique = [...new Set(cuisines.filter(Boolean))];
  if (unique.length === 0) return Array(WEEK_DAYS).fill(null);
  const recentSet = new Set(recent);
  // Shuffle, then put cuisines not eaten last week first (stable within each group).
  const order = shuffle(unique, random).sort((a, b) => Number(recentSet.has(a)) - Number(recentSet.has(b)));
  // Round-robin: with 2+ cuisines, consecutive days always differ.
  return Array.from({ length: WEEK_DAYS }, (_, day) => order[day % order.length]);
}

function pickProteins(settings: WeekSlateInput['settings'], random: () => number): string[] {
  const pool = allowedProteins(settings);
  if (pool.length === 0) return Array(WEEK_DAYS).fill(ANY_PROTEIN);

  const capFor = (protein: string) => {
    if (protein === VEGETARIAN_NIGHT) return 1;
    return MAX_PROTEIN_PER_WEEK;
  };
  const meatNightsCap = settings.dietaryType === 'flexitarian' ? FLEXITARIAN_MEAT_NIGHTS : Infinity;
  const mustInclude = pool.includes(VEGETARIAN_NIGHT) ? [VEGETARIAN_NIGHT] : [];

  const picks: string[] = [];
  const counts = new Map<string, number>();
  let meatNights = 0;
  for (let day = 0; day < WEEK_DAYS; day++) {
    const previous = picks[day - 1];
    const daysLeft = WEEK_DAYS - day;
    const missing = mustInclude.filter((p) => !counts.get(p));
    const fits = (protein: string, strictCap: boolean) =>
      protein !== previous &&
      (!strictCap || (counts.get(protein) ?? 0) < capFor(protein)) &&
      (!MEAT_OR_FISH.has(protein) || meatNights < meatNightsCap);
    // Least-used first, random among ties, so the week spreads across the pool.
    const candidates = shuffle(pool, random).sort((a, b) => (counts.get(a) ?? 0) - (counts.get(b) ?? 0));
    const choice =
      (missing.length >= daysLeft ? missing.find((p) => fits(p, true)) : undefined) ??
      candidates.find((p) => fits(p, true)) ??
      // The diet leaves too few proteins for the cap: allow a third, still never on consecutive days.
      candidates.find((p) => p !== previous && p !== VEGETARIAN_NIGHT && (!MEAT_OR_FISH.has(p) || meatNights < meatNightsCap)) ??
      candidates.find((p) => p !== previous) ??
      candidates[0];
    picks.push(choice);
    counts.set(choice, (counts.get(choice) ?? 0) + 1);
    if (MEAT_OR_FISH.has(choice)) meatNights++;
  }
  return picks;
}

function methodsFor(type: DayType, effort: FamilySettings['effortPreference']): string[] {
  if (type === 'weekend') return WEEKEND_METHODS;
  return effort === 'minimal_clean_up' ? LOW_CLEANUP_METHODS : WEEKNIGHT_METHODS;
}

function pickMethods(types: DayType[], effort: FamilySettings['effortPreference'], random: () => number): string[] {
  const weeknight = shuffle(methodsFor('weeknight', effort), random);
  const picks: string[] = [];
  types.forEach((type, day) => {
    const previous = picks[day - 1];
    if (type === 'weeknight') {
      // Rotate; a 3-method low-clean-up list still never repeats on consecutive nights.
      picks.push(weeknight[day % weeknight.length]);
    } else {
      const used = countOf(picks);
      const options = shuffle(WEEKEND_METHODS, random).sort((a, b) => (used.get(a) ?? 0) - (used.get(b) ?? 0));
      picks.push(options.find((method) => method !== previous) ?? options[0]);
    }
  });
  return picks;
}

/**
 * Pantry items that are a protein, and the day proteins that can use them.
 * "chicken thighs" belongs on a chicken day, never a fish or meat-free one.
 */
const PROTEIN_ITEMS: { words: string[]; days: string[] }[] = [
  { words: ['chicken'], days: ['chicken'] },
  { words: ['beef', 'steak'], days: ['beef'] },
  { words: ['pork', 'bacon', 'ham', 'sausage'], days: ['pork'] },
  { words: ['lamb'], days: ['lamb'] },
  { words: ['fish', 'salmon', 'tuna', 'barramundi', 'snapper', 'cod', 'trout'], days: ['fish'] },
  { words: ['prawn', 'shrimp', 'squid', 'calamari', 'mussel', 'scallop', 'crab'], days: ['seafood'] },
  { words: ['egg'], days: ['eggs', VEGETARIAN_NIGHT] },
  { words: ['tofu'], days: ['tofu', VEGETARIAN_NIGHT] },
  { words: ['tempeh'], days: ['tempeh'] },
  { words: ['halloumi'], days: ['halloumi', VEGETARIAN_NIGHT] },
  { words: ['paneer'], days: ['paneer', VEGETARIAN_NIGHT] },
  { words: ['lentil', 'chickpea', 'bean'], days: ['legumes', VEGETARIAN_NIGHT] },
];

/** The day proteins a protein-type pantry item fits, or null for any other item. */
function proteinDaysFor(item: string): string[] | null {
  const match = PROTEIN_ITEMS.find(({ words }) => words.some((word) => new RegExp(`\\b${word}(?:s|es)?\\b`, 'i').test(item)));
  return match ? match.days : null;
}

/**
 * Use-soon meat, fish or tofu should be cooked early: if none of Monday–
 * Wednesday has the matching protein, swap it in from later in the week,
 * keeping consecutive days different. Leaves the week alone if it can't.
 */
function bringUseSoonProteinsForward(proteins: string[], useSoonItems: string[]): string[] {
  const week = [...proteins];
  const differsFromNeighbours = (day: number) =>
    (day === 0 || week[day - 1] !== week[day]) && (day === week.length - 1 || week[day + 1] !== week[day]);
  for (const item of useSoonItems) {
    const fits = proteinDaysFor(item);
    if (!fits || [0, 1, 2].some((day) => fits.includes(week[day]))) continue;
    swap: for (let later = 3; later < week.length; later++) {
      if (!fits.includes(week[later])) continue;
      for (const early of [0, 1, 2]) {
        [week[early], week[later]] = [week[later], week[early]];
        if (differsFromNeighbours(early) && differsFromNeighbours(later)) break swap;
        [week[early], week[later]] = [week[later], week[early]];
      }
    }
  }
  return week;
}

/** The days an item may go on: any day, or only days whose protein it is. */
function eligibleDays(item: string, dayProteins: string[]): number[] {
  const all = dayProteins.map((_, i) => i);
  const fits = proteinDaysFor(item);
  return fits ? all.filter((day) => fits.includes(dayProteins[day])) : all;
}

/**
 * Use-soon items on Monday–Wednesday, the rest spread across the week, at
 * most 3 per day. A protein item only goes on a day with that protein; with
 * none this week it's left out of the focus (it stays in the pantry list).
 */
function pickPantryFocus(pantryItems: string[], useSoonItems: string[], dayProteins: string[]): string[][] {
  const days: string[][] = Array.from({ length: WEEK_DAYS }, () => []);
  const key = (item: string) => item.trim().toLowerCase();
  const soonKeys = new Set(useSoonItems.map(key));
  const soon = [...new Map(useSoonItems.filter((i) => i.trim()).map((i) => [key(i), i.trim()])).values()];
  const rest = [
    ...new Map(pantryItems.filter((i) => i.trim() && !soonKeys.has(key(i))).map((i) => [key(i), i.trim()])).values(),
  ];

  // Puts the item on the emptiest day in `dayOrder` that can take it (earlier wins ties).
  const place = (item: string, dayOrder: number[]): boolean => {
    const eligible = new Set(eligibleDays(item, dayProteins));
    const day = dayOrder
      .filter((d) => eligible.has(d) && days[d].length < MAX_PANTRY_FOCUS)
      .sort((a, b) => days[a].length - days[b].length)[0];
    if (day === undefined) return false;
    days[day].push(item);
    return true;
  };
  // Use-soon items on Monday–Wednesday, or later in the week if those can't take them.
  soon.forEach((item) => place(item, [0, 1, 2]) || place(item, [3, 4, 5, 6]));
  // The rest fill the later days first, so Monday–Wednesday keep room for what's urgent.
  rest.forEach((item) => place(item, [3, 4, 5, 6, 0, 1, 2]));
  return days;
}

function countOf(values: (string | null | undefined)[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const value of values) if (value) counts.set(value, (counts.get(value) ?? 0) + 1);
  return counts;
}

/** Fisher–Yates on a copy. */
function shuffle<T>(items: readonly T[], random: () => number): T[] {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

/** Small seeded PRNG: the same seed always gives the same week. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A fresh seed per plan. */
export function newSlateSeed(): number {
  return Math.floor(Math.random() * 2 ** 32);
}
